import{at as e,it as t,n,vt as r}from"./chunks/framework.BFUVyeTq.js";var i=JSON.parse(`{"title":"Limitations","description":"","frontmatter":{},"headers":[],"relativePath":"guide/solid-protocol/limitations.md","filePath":"guide/solid-protocol/limitations.md"}`),a={name:`guide/solid-protocol/limitations.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to “Limitations”">​</a></h1><p>Given the nature of Solid and RDF, there are some things to keep in mind when declaring your schemas:</p><ul><li>Field declarations don&#39;t support the entire Zod API, it is limited to RDF-compatible fields. For example, basic types like <code>z.number()</code> or <code>z.date()</code> are fine, but nested objects or types like <code>z.symbol()</code> will not work.</li><li>Soukai can only write models to authoritative documents (documents with the same url as the resource), though it&#39;s possible to read from non-authoritative sources.</li><li><code>null</code> and <code>undefined</code> attributes will be treated the same way when saved (casted to <code>undefined</code>), given that RDF can&#39;t represent null values.</li><li>In array fields, an empty array will also be stored as a missing property. You can use <code>.default([])</code> in your field definitions to make sure that you always get an array.</li><li><a href="https://github.com/NoelDeMartin/soukai/issues/5" target="_blank" rel="noreferrer">#5</a> Blank nodes are not supported.</li><li><a href="https://github.com/NoelDeMartin/soukai/issues/9" target="_blank" rel="noreferrer">#9</a> Arrays cannot have duplicated entries, given that RDF is monotonic.</li></ul>`,3)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};